// Разблокировка звука для iOS Safari / Telegram WebView / встраивания в iframe.
// Подключается в <head> ДО index.js (export_presets.cfg → html/head_include и оболочка хостинга).
//  1. Запоминаем каждый AudioContext, который создаст движок Godot.
//  2. На каждом жесте (touchend/pointerup/click/keydown) синхронно зовём ctx.resume():
//     iOS разрешает запуск аудио только внутри обработчика жеста, а после звонка или
//     сворачивания приложения переводит контекст в "interrupted" — его тоже надо будить.
//  3. Беззвучный режим айфона глушит Web Audio (категория "ambient"). navigator.audioSession
//     = "playback" (iOS 17+) или бесшумный <audio> в цикле (iOS ≤ 16) переводят сессию
//     в режим медиаплеера — игра звучит, как видео.
(function () {
	'use strict';
	var SILENT_URL = window.GODOT_SILENT_AUDIO_URL || 'data:audio/mpeg;base64,';
	var contexts = [];
	var NativeContext = window.AudioContext || window.webkitAudioContext;
	if (NativeContext) {
		var Tracked = function (options) {
			var ctx = options === undefined ? new NativeContext() : new NativeContext(options);
			contexts.push(ctx);
			return ctx;
		};
		Tracked.prototype = NativeContext.prototype;
		window.AudioContext = Tracked;
		if (window.webkitAudioContext) {
			window.webkitAudioContext = Tracked;
		}
	}

	var silent = null;

	function keepSessionPlayback() {
		try {
			if (navigator.audioSession && navigator.audioSession.type !== 'playback') {
				navigator.audioSession.type = 'playback';
				return;
			}
		} catch (e) {
			// Старый WebKit без Audio Session API — ниже сработает бесшумный <audio>.
		}
		if (navigator.audioSession) {
			return;
		}
		if (!/iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent) || !('ontouchend' in document)) {
			return;
		}
		if (silent === null) {
			silent = document.createElement('audio');
			silent.setAttribute('x-webkit-airplay', 'deny');
			silent.setAttribute('playsinline', '');
			silent.preload = 'auto';
			silent.loop = true;
			silent.src = SILENT_URL;
		}
		if (silent.paused && !document.hidden) {
			var played = silent.play();
			if (played && played.catch) {
				played.catch(function () {});
			}
		}
	}

	function unlock() {
		keepSessionPlayback();
		for (var i = 0; i < contexts.length; i++) {
			var ctx = contexts[i];
			if (ctx.state !== 'running' && ctx.state !== 'closed') {
				var resumed = ctx.resume();
				if (resumed && resumed.catch) {
					resumed.catch(function () {});
				}
			}
		}
	}

	['touchend', 'pointerup', 'mouseup', 'click', 'keydown'].forEach(function (type) {
		window.addEventListener(type, unlock, { capture: true, passive: true });
	});
	document.addEventListener('visibilitychange', function () {
		if (silent === null) {
			return;
		}
		if (document.hidden) {
			silent.pause();
		}
	});
	window.__godotAudioContexts = contexts;
}());
